  if(!Array.isArray(out.lumber)||!out.lumber.some(x=>x.grade))out.lumber=structuredClone(base.lumber);
  out.lumber.forEach(x=>{x.grade=Math.min(4,Math.max(1,Number(x.grade)||2));x.category=x.category||'raw';x.family=x.family||(/2[×x]6/.test(x.size)?'2x6':/4[×x]4/.test(x.size)?'4x4':/4[×x]6/.test(x.size)?'4x6':'2x4');if(x.category==='raw')x.lengthFt=Number(x.lengthFt)||Number((String(x.size).match(/(\d+(?:\.\d+)?)\s*ft/i)||[])[1])||8});
