function familyForBoard(width){return Number(width)===6?'2x6':'2x4'}
function availableOf(x){return Math.max(0,(Number(x.qty)||0)-(Number(x.reserved)||0))}
function orderProducts(o){if(Array.isArray(o.products)&&o.products.length)return o.products; if(o.palletSpec)return [{...o.palletSpec,qty:Number(o.qty)||1,length:o.loadItems?.[0]?.length||parseProductMeasure(o.product)?.length,width:o.loadItems?.[0]?.width||parseProductMeasure(o.product)?.width,name:o.product}];return []}

