function componentRequirements(spec){
  if(Array.isArray(spec?.products))return spec.products.flatMap(p=>componentRequirements(p));
  const qty=Math.max(1,Number(spec?.qty)||1),out=[],type=palletTypeRules(spec?.type||spec?.ways),allow=spec?.allowConversions||{};
  if(type.base==='runner'&&Number(spec.runners)>0)out.push({label:'Runners 2×4',family:'2x4',count:qty*Number(spec.runners),cutLength:Number(spec.length)||1,grade:Number(spec.runnerGrade)||2,allow});
  if(type.base==='block'){
    const blocks=Array.isArray(spec.blocks)&&spec.blocks.length?spec.blocks:[{family:'4x4',length:4,qty:9,grade:1}];
    for(const b of blocks)if(Number(b.qty)>0)out.push({label:`Blocks ${b.family} × ${b.length} in`,family:b.family||'4x4',count:qty*Number(b.qty),cutLength:Number(b.length)||4,grade:Number(b.grade)||1,allow});
  }
  if(type.base==='crate'&&Number(spec.basePieces)>0)out.push({label:'Base de crate 2×4',family:'2x4',count:qty*Number(spec.basePieces),cutLength:Number(spec.length)||1,grade:Number(spec.runnerGrade)||2,allow});
  for(const [side,rows] of [['Arriba',spec?.topBoards||[]],['Abajo',spec?.bottomBoards||[]]])for(const r of rows)if(Number(r.qty)>0)out.push({label:`${side} 1×${r.width} × ${Number(r.length)||Number(spec.width)||1} in`,family:familyForBoard(r.width),count:qty*Number(r.qty),cutLength:Number(r.length)||Number(spec.width)||1,grade:Number(r.grade)||2,allow,ripFactor:2});
  return out
}
function conversionSuggestions(shortages){
  const out=[];
  for(const req of shortages||[]){
    if(req.family==='2x4'&&req.allow?.from4x4){const stocks=state.lumber.filter(x=>x.category==='raw'&&x.family==='4x4'&&Number(x.grade)<=req.grade&&availableOf(x)>0);for(const x of stocks){const longitudinal=Math.floor((Number(x.lengthFt)||8)*12/req.cutLength),yieldPer=Math.max(0,longitudinal*2);if(yieldPer)out.push({target:'2x4',sourceId:x.id,source:x.size,needed:req.missing,rawNeeded:Math.ceil(req.missing/yieldPer),yieldPer,label:req.label})}}
    if(req.family==='2x6'&&req.allow?.from4x6){const stocks=state.lumber.filter(x=>x.category==='raw'&&x.family==='4x6'&&Number(x.grade)<=req.grade&&availableOf(x)>0);for(const x of stocks){const longitudinal=Math.floor((Number(x.lengthFt)||8)*12/req.cutLength),yieldPer=Math.max(0,longitudinal*2);if(yieldPer)out.push({target:'2x6',sourceId:x.id,source:x.size,needed:req.missing,rawNeeded:Math.ceil(req.missing/yieldPer),yieldPer,label:req.label})}}
  }
  return out.sort((a,b)=>a.rawNeeded-b.rawNeeded)
}
function buildMaterialPlan(spec){
  const reqs=componentRequirements(spec),avail=Object.fromEntries(state.lumber.map(x=>[x.id,availableOf(x)])),alloc=[],shortages=[];let waste=0;
  const ordered=reqs.slice().sort((a,b)=>b.cutLength-a.cutLength||b.count-a.count);
  for(const req of ordered){let remain=req.count;
    // 1) usar primero piezas ya cortadas exactamente a la medida
    const finished=state.lumber.filter(x=>x.category==='finished'&&x.family===req.family&&Number(x.pieceLengthIn)===Number(req.cutLength)&&Number(x.grade)<=req.grade&&avail[x.id]>0).sort((a,b)=>Number(b.grade)-Number(a.grade));
    for(const x of finished){if(remain<=0)break;const yp=Math.max(1,Number(req.ripFactor)||1),pieces=Math.min(avail[x.id],Math.ceil(remain/yp));if(!pieces)continue;const produced=Math.min(remain,pieces*yp);alloc.push({stockId:x.id,stock:x.size,grade:x.grade,component:req.label,cutLength:req.cutLength,rawPieces:pieces,yieldPerPiece:yp,produced,wasteIn:0,category:'finished'});avail[x.id]-=pieces;remain-=produced}
    // 2) después cortar materia prima de la familia correcta; nunca convertir 4x4/4x6 solo
    const opts=state.lumber.map(x=>{if(x.category!=='raw'||x.family!==req.family)return null;const raw=(Number(x.lengthFt)||8)*12,longitudinal=Math.floor(raw/req.cutLength),rip=Math.max(1,Number(req.ripFactor)||1),y=longitudinal*rip;return y>0?{x,raw,y,w:(raw-longitudinal*req.cutLength)/Math.max(1,y),exact:Number(x.grade)===req.grade}:null}).filter(Boolean).filter(o=>Number(o.x.grade)<=req.grade&&avail[o.x.id]>0).sort((a,b)=>a.w-b.w||(b.exact-a.exact)||a.raw-b.raw);
    for(const o of opts){if(remain<=0)break;const pieces=Math.min(avail[o.x.id],Math.ceil(remain/o.y));if(!pieces)continue;const produced=Math.min(remain,pieces*o.y);alloc.push({stockId:o.x.id,stock:o.x.size,grade:o.x.grade,component:req.label,cutLength:req.cutLength,rawPieces:pieces,yieldPerPiece:o.y,produced,wasteIn:pieces*o.raw-produced*req.cutLength,category:'raw'});avail[o.x.id]-=pieces;remain-=produced;waste+=pieces*o.raw-produced*req.cutLength}
    if(remain>0)shortages.push({...req,missing:remain})
  }
  const agg={};for(const a of alloc)agg[a.stockId]=(agg[a.stockId]||0)+a.rawPieces;
  return {allocations:alloc,stockTotals:agg,shortages,wasteIn:waste,totalRaw:Object.values(agg).reduce((a,b)=>a+b,0),requirements:reqs,conversionSuggestions:conversionSuggestions(shortages)}
}
function buildOrderMaterialPlan(order){const products=orderProducts(order);return buildMaterialPlan({products})}
function reserveWood(order){const plan=buildOrderMaterialPlan(order);if(plan.shortages.length){order.materialPlan=plan;return false}for(const [id,n] of Object.entries(plan.stockTotals)){const w=lumberById(id);if(!w||availableOf(w)<n)return false}for(const [id,n] of Object.entries(plan.stockTotals))lumberById(id).reserved+=n;order.materialPlan=plan;order.materialReservation=plan.stockTotals;order.woodNeed=plan.totalRaw;save();return true}
function consumeReservedWood(order){for(const [id,n] of Object.entries(order.materialReservation||{})){const w=lumberById(id);if(!w)continue;w.qty=Math.max(0,w.qty-n);w.reserved=Math.max(0,w.reserved-n)}order.materialReservation={};save()}
function findFinished(sku){let f=state.finished.find(x=>x.sku===sku);if(!f){f={sku,qty:0,reserved:0};state.finished.push(f)}return f}
function parseProductMeasure(text){
  const m=String(text||'').match(/(\d+(?:\.\d+)?)\s*[×xX]\s*(\d+(?:\.\d+)?)/);
  return m?{length:Number(m[1]),width:Number(m[2])}:null;
}
function loadItemsFor(order){
  if(Array.isArray(order.loadItems)&&order.loadItems.length)return clone(order.loadItems);
  const products=orderProducts(order);if(products.length)return products.map(p=>{const r=palletTypeRules(p.type);return {name:p.name||`${p.length}×${p.width}`,length:Number(p.length),width:Number(p.width),quantity:Number(p.qty)||1,maxHeight:r.maxHeight,canRotate:r.canRotate,type:p.type}});
  const m=parseProductMeasure(order.product);if(!m)return [];return [{name:`${m.length}×${m.width}`,length:m.length,width:m.width,quantity:Number(order.qty)||1,maxHeight:20,canRotate:true,type:'4-way-runner'}]
}
function loadTotal(items){return (items||[]).reduce((n,x)=>n+(Number(x.quantity)||0),0)}

function renderInicio(){
  const active=state.orders.filter(o=>o.stage!=='completed').length, ready=state.orders.filter(o=>o.stage==='ready_load').length, prod=state.orders.filter(o=>['waiting_material','cutting','material_ready','building'].includes(o.stage)).length, low=state.lumber.filter(x=>x.qty-x.reserved<x.min).length;
  return `<div class="grid metrics">${metric('Órdenes activas',active,'En toda la operación')}${metric('Listas para cargar',ready,'Ya fabricadas y liberadas')}${metric('Producción en curso',prod,'Corte + fabricación')}${metric('Alertas de madera',low,'Debajo del mínimo disponible')}</div>
  <div class="section"><div class="section-head"><div><h2>Módulos</h2><p>Todos comparten las mismas órdenes; el prototipo permite moverlas por etapas.</p></div></div><div class="grid module-grid">${moduleCard('ordenes','＋','Órdenes','Crear una orden en dos pasos y reutilizar plantillas.')}${moduleCard('madera','▦','Inventario de madera','Materia prima, piezas listas y catálogo configurable.')}${moduleCard('conversion','⇄','Conversión de madera','Convertir manualmente 4×4→2×4 o 4×6→2×6 cuando tú lo autorices.')}${moduleCard('produccion','✂','Producción / Corte','Reservar madera, iniciar corte y liberar material.')}${moduleCard('fabricacion','⚒','Fabricación','Recibir aviso, armar pallets y liberarlos.')}${moduleCard('terminados','▣','Inventario de pallets','Producto terminado y reservado.')}${moduleCard('carga','▰','Carga y despacho','Optimizar, cargar, evidencia, firma y salida.')}${moduleCard('reportes','▥','Reportes','Resumen operativo sin crear menús innecesarios.')}</div></div>
  <div class="section grid two-col"><div class="card"><div class="section-head"><div><h2>Flujo real de una orden</h2><p>Cada botón mueve la misma orden al siguiente módulo.</p></div></div><div class="timeline"><span class="node">Inventario</span><span class="arrow">→</span><span class="node">Corte</span><span class="arrow">→</span><span class="node">Material listo</span><span class="arrow">→</span><span class="node">Fabricación</span><span class="arrow">→</span><span class="node">Carga</span><span class="arrow">→</span><span class="node">Historial</span></div><div style="height:14px"></div><button class="btn" data-go="ordenes">Crear / revisar órdenes</button></div><div class="card"><h2 style="font-size:17px;margin-top:0">Avisos automáticos</h2>${state.notifications.slice(0,4).map(n=>`<div class="notification ${n.kind==='ok'?'ok':''}" style="margin-bottom:8px">${n.text}</div>`).join('')||'<div class="small">Sin avisos.</div>'}</div></div>`
}
function renderMadera(){const raw=state.lumber.filter(x=>x.category==='raw'),finished=state.lumber.filter(x=>x.category==='finished');const rows=list=>list.map(x=>{const a=availableOf(x);return `<tr><td><b>${x.size}</b><div class="small">${x.family}</div></td><td><b>#${x.grade}</b></td><td>${x.qty}</td><td>${x.reserved||0}</td><td>${a}</td><td>${x.min||0}</td><td>${a<(x.min||0)?pill('Bajo','yellow'):pill('Bien','green')}</td></tr>`}).join('');return `<div class="toolbar"><button class="btn" data-action="receiveWood">+ Recibir madera</button><button class="btn secondary" data-action="addMaterial">+ Agregar tipo de madera</button><button class="btn secondary" data-go="conversion">Conversión manual</button></div><div class="section-head"><div><h2>Materia prima</h2><p>2×4, 2×6, 4×4, 4×6 y cualquier medida que agregues al catálogo.</p></div></div><div class="table-wrap"><table><thead><tr><th>Medida</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(raw)}</tbody></table></div><div class="section-head section"><div><h2>Piezas ya cortadas</h2><p>El planificador usa estas piezas primero antes de cortar madera larga.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pieza lista</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(finished)||'<tr><td colspan="7">Sin piezas listas.</td></tr>'}</tbody></table></div><div class="section notification info"><b>Regla:</b> producción usa primero piezas listas; después corta 2×4/2×6 de inventario. 4×4 y 4×6 nunca se convierten automáticamente.</div>`}
function renderConversion(){const sources=state.lumber.filter(x=>x.category==='raw'&&['4x4','4x6'].includes(x.family));return `<div class="grid metrics">${metric('4×4 disponible',sources.filter(x=>x.family==='4x4').reduce((n,x)=>n+availableOf(x),0),'Solo si tú decides convertir')}${metric('4×6 disponible',sources.filter(x=>x.family==='4x6').reduce((n,x)=>n+availableOf(x),0),'Solo si tú decides convertir')}${metric('Conversiones automáticas','0','Nunca sin autorización')}${metric('Control','Manual','Tú eliges fuente y cantidad')}</div><div class="section card"><h2 style="font-size:17px;margin-top:0">Conversión manual de madera</h2><p class="small">El sistema puede sugerir una conversión cuando falta material, pero aquí eres tú quien decide ejecutarla.</p><div class="form-grid"><label><span>Madera fuente</span><select id="convSource">${sources.map(x=>`<option value="${x.id}">${x.size} · #${x.grade} · disp. ${availableOf(x)}</option>`).join('')}</select></label><label><span>Cantidad a convertir</span><input id="convQty" type="number" min="1" value="1"></label></div><div class="dialog-actions"><button class="btn" data-action="convertWood">Convertir seleccionada</button></div><div class="notification info">4×4 genera 2×4 de igual largo y calidad; 4×6 genera 2×6. En este prototipo se usa un rendimiento de 2 piezas por pieza fuente.</div></div>`}
function orderMaterialSummary(o){
  const p=o.materialPlan||buildOrderMaterialPlan(o);
  if(p.shortages?.length){
    const first=p.shortages[0],suggest=(p.conversionSuggestions||[]).length;
    return `<span class="pill red">Falta material</span><div class="small">${first.label}: faltan ${first.missing}${suggest?` · ${suggest} sugerencia(s) de conversión`:''}</div>`
  }
  const ready=(p.allocations||[]).filter(a=>a.category==='finished').reduce((n,a)=>n+a.rawPieces,0),raw=(p.allocations||[]).filter(a=>a.category==='raw').reduce((n,a)=>n+a.rawPieces,0);
  return `<span class="pill green">Material disponible</span><div class="small">${ready} piezas listas + ${raw} piezas madre · desperdicio ${Math.round(p.wasteIn||0)} in</div>`
}
function renderOrdenes(){const rows=state.orders.filter(o=>o.stage!=='completed');return `<div class="toolbar"><button class="btn" data-action="newOrder">+ Nueva orden</button><input id="ordersSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Entrega</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>${rows.map(o=>{const search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();return `<tr data-order-row data-search="${search.replace(/"/g,'&quot;')}"><td><b>#${o.id}</b>${o.clientOrder?`<div class="small">Cliente: ${o.clientOrder}</div>`:''}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${o.shipping==='pickup'?'Recogida cliente':'Envío fábrica'}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td><button class="btn secondary" data-order-spec="${o.id}">Especificación</button></td></tr>`}).join('')}</tbody></table></div><div class="section notification info"><b>Una sola entrada.</b> La orden se crea aquí y el mismo registro viaja por Corte → Fabricación → Carga → Historial.</div>`}
function renderProduccion(){const rows=state.orders.filter(o=>['waiting_material','cutting','material_ready'].includes(o.stage));return `<div class="toolbar"><button class="btn secondary" data-go="ordenes">Ir a Órdenes</button><button class="btn secondary" data-action="autoPlan">Recalcular planes de corte</button><input id="productionSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Etapa</th><th>Plan automático de madera</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>{let action=o.stage==='waiting_material'?`<button class="btn" data-cut-start="${o.id}">Reservar e iniciar corte</button>`:o.stage==='cutting'?`<button class="btn" data-cut-ready="${o.id}">Material listo</button>`:`<span class="small">Esperando fabricación</span>`;const search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();return `<tr data-production-row data-search="${search.replace(/"/g,'&quot;')}"><td><b>#${o.id}</b>${o.clientOrder?`<div class="small">Cliente: ${o.clientOrder}</div>`:''}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${orderMaterialSummary(o)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="7">No hay órdenes en esta etapa.</td></tr>'}</tbody></table></div><div class="section card"><b>Planificador de corte v0.8</b><p class="small">Ya no seleccionas manualmente 8, 10, 12 o 16 pies. Usa primero piezas ya cortadas; después compara materia prima 2×4/2×6 de inventario por largo, rendimiento y calidad. Si falta material, solo sugiere conversiones autorizadas; no convierte nada por sí solo.</p></div>`}
function renderFabricacion(){const rows=state.orders.filter(o=>['material_ready','building'].includes(o.stage));return `<div class="grid metrics">${metric('Material listo',rows.filter(o=>o.stage==='material_ready').length,'Puede recogerlo el armador')}${metric('En fabricación',rows.filter(o=>o.stage==='building').length,'Trabajo activo')}${metric('Listas para carga',state.orders.filter(o=>o.stage==='ready_load').length,'Ya fabricadas')}${metric('Avisos',state.notifications.length,'Eventos recientes')}</div><div class="section table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>`<tr><td>#${o.id}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${o.stage==='material_ready'?`<button class="btn" data-build-start="${o.id}">Iniciar fabricación</button>`:`<button class="btn" data-build-ready="${o.id}">Terminar y liberar</button>`}</td></tr>`).join('')||'<tr><td colspan="6">No hay órdenes en fabricación.</td></tr>'}</tbody></table></div><div class="section notification ok"><b>Aviso automático:</b> cuando Corte libera material, Fabricación lo ve aquí sin que nadie tenga que ir a avisar personalmente.</div>`}
function renderTerminados(){const total=state.finished.reduce((s,x)=>s+x.qty,0),res=state.finished.reduce((s,x)=>s+x.reserved,0);return `<div class="grid metrics">${metric('Fabricados',total,'Inventario actual')}${metric('Reservados',res,'Asignados a órdenes')}${metric('Disponibles',total-res,'Sin reservar')}${metric('Listos para carga',state.orders.filter(o=>o.stage==='ready_load').reduce((s,o)=>s+o.qty,0),'Pallets liberados')}</div><div class="section table-wrap"><table><thead><tr><th>SKU</th><th>Existencia</th><th>Reservado</th><th>Disponible</th></tr></thead><tbody>${state.finished.map(x=>`<tr><td><b>${x.sku}</b></td><td>${x.qty}</td><td>${x.reserved}</td><td>${x.qty-x.reserved}</td></tr>`).join('')}</tbody></table></div>`}
function shipPill(o){if(o.shipping==='pickup')return pill('Recogida del cliente','blue');if(o.stage==='transit')return pill('En tránsito','pink');return pill('Envío de fábrica','yellow')}
function renderCarga(){const rows=state.orders.filter(o=>o.stage!=='completed');return `<div class="toolbar"><button class="btn secondary" id="openLoadMaster">Abrir LoadMaster AI</button><input id="loadSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"><select><option>Todos</option><option>Envío de fábrica</option><option>Recogida del cliente</option><option>En tránsito</option></select></div><div class="grid two-col"><div><h2 style="font-size:16px">Pedidos y planificación de carga</h2>${rows.map(o=>{const ready=['ready_load','loading','transit'].includes(o.stage);const search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();let action='';if(o.stage==='transit')action=`<button class="btn" data-transit-done="${o.id}">Marcar entregado</button>`;else if(ready)action=`<button class="btn" data-load-order="${o.id}">${o.stage==='loading'?'Continuar carga':(o.shipping==='pickup'?'Iniciar recogida':'Optimizar / iniciar carga')}</button>`;else action=`<button class="btn secondary" data-plan-load="${o.id}">Planear en LoadMaster</button><div class="small" style="margin-top:6px">Aún no se puede despachar: ${stageLabel(o.stage)}.</div>`;return `<div class="card order-card" data-load-card data-search="${search.replace(/"/g,'&quot;')}"><div class="order-card-top"><div>${shipPill(o)}<h3 style="margin:9px 0 3px">${o.customer}</h3><div class="small">Orden interna #${o.id}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}</div><div class="small">${o.qty} pallets · ${o.product}</div>${progressFor(o.stage)}</div><div style="text-align:right"><div class="small">Estado</div><b>${stageLabel(o.stage)}</b><div style="height:8px"></div>${action}</div></div></div>`}).join('')||'<div class="empty-state">No hay pedidos.</div>'}</div><aside><div class="card"><h2 style="font-size:16px;margin-top:0">Planificación anticipada</h2><p class="small">Una orden aparece aquí desde que se crea. LoadMaster puede planearla antes de fabricar, pero los botones de carga y despacho solo se habilitan cuando Fabricación la libera.</p></div><div class="card" style="margin-top:12px"><h2 style="font-size:16px;margin-top:0">Colores de despacho</h2><div>${pill('Envío de fábrica','yellow')}<div class="small" style="margin:5px 4px 12px">La fábrica pone tráiler y chofer.</div>${pill('Recogida del cliente','blue')}<div class="small" style="margin:5px 4px 12px">El cliente llega con su propio tráiler.</div>${pill('En tránsito','pink')}<div class="small" style="margin:5px 4px">El chofer de la fábrica va camino al cliente.</div></div></div></aside></div>`}
function renderReportes(){const completed=state.history.length;return `<div class="grid metrics">${metric('Órdenes activas',state.orders.filter(o=>o.stage!=='completed').length,'Operación actual')}${metric('Pallets terminados',state.finished.reduce((s,x)=>s+x.qty,0),'Inventario')}${metric('Despachos históricos',completed,'En este demo')}${metric('Retención',state.settings.historyDays+' días','Configurable')}</div><div class="section grid two-col"><div class="card"><h2 style="font-size:16px;margin-top:0">Resumen por etapa</h2><div class="status-list">${['waiting_material','cutting','material_ready','building','ready_load','transit'].map(s=>`<div class="status-row"><span class="dot"></span><div>${stageLabel(s)}</div><b>${state.orders.filter(o=>o.stage===s).length}</b></div>`).join('')}</div></div><div class="card"><h2 style="font-size:16px;margin-top:0">Idea de producción sumario</h2><p class="small">Este módulo concentra la información de productividad sin obligar a crear un menú separado para cada reporte.</p></div></div>`}
function renderHistorial(){return `<div class="toolbar"><label class="small">Retención <select id="historyDays"><option value="30" ${state.settings.historyDays===30?'selected':''}>30 días</option><option value="60" ${state.settings.historyDays===60?'selected':''}>60 días</option><option value="90" ${state.settings.historyDays===90?'selected':''}>90 días</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Tipo</th><th>Completado</th><th>Evidencia</th></tr></thead><tbody>${state.history.map(h=>`<tr><td>#${h.id}${h.clientOrder?`<div class="small">Cliente: ${h.clientOrder}</div>`:''}</td><td>${h.customer}</td><td>${h.shipping==='pickup'?'Recogida cliente':'Envío fábrica'}</td><td>${h.completed}</td><td>${h.evidence}</td></tr>`).join('')||'<tr><td colspan="5">Sin historial.</td></tr>'}</tbody></table></div><div class="section notification">El prototipo guarda el historial en el navegador. En la plataforma real, la retención podrá archivar o purgar automáticamente según la política que se decida.</div>`}
function render(){const [t,s]=views[currentView];el.title.textContent=t;el.subtitle.textContent=s;el.content.innerHTML=({inicio:renderInicio,ordenes:renderOrdenes,madera:renderMadera,conversion:renderConversion,produccion:renderProduccion,fabricacion:renderFabricacion,terminados:renderTerminados,carga:renderCarga,reportes:renderReportes,historial:renderHistorial})[currentView]();bindDynamic()}
function navigate(v){currentView=v;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.getElementById('sidebar').classList.remove('open');render()}
function openDialog(title,subtitle,body){el.dialogTitle.textContent=title;el.dialogSubtitle.textContent=subtitle||'';el.dialogBody.innerHTML=body;el.dialog.showModal()}
function closeDialog(){el.dialog.close()}
function bindDynamic(){
  document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>navigate(x.dataset.go));
  document.querySelectorAll('[data-cut-start]').forEach(x=>x.onclick=()=>startCut(x.dataset.cutStart));
  document.querySelectorAll('[data-cut-ready]').forEach(x=>x.onclick=()=>finishCut(x.dataset.cutReady));
  document.querySelectorAll('[data-build-start]').forEach(x=>x.onclick=()=>startBuild(x.dataset.buildStart));
  document.querySelectorAll('[data-build-ready]').forEach(x=>x.onclick=()=>finishBuild(x.dataset.buildReady));
  document.querySelectorAll('[data-load-order]').forEach(x=>x.onclick=()=>openLoadOrder(x.dataset.loadOrder));
  document.querySelectorAll('[data-plan-load]').forEach(x=>x.onclick=()=>openLoadPreparation(x.dataset.planLoad));
  document.querySelectorAll('[data-order-spec]').forEach(x=>x.onclick=()=>openOrderSpecification(x.dataset.orderSpec));
  document.querySelectorAll('[data-transit-done]').forEach(x=>x.onclick=()=>completeDelivery(x.dataset.transitDone));
  document.getElementById('openLoadMaster')?.addEventListener('click',openLoadMaster);
  document.querySelector('[data-action="receiveWood"]')?.addEventListener('click',receiveWoodDialog);
  document.querySelector('[data-action="addMaterial"]')?.addEventListener('click',addMaterialDialog);
  document.querySelector('[data-action="convertWood"]')?.addEventListener('click',convertWoodFromView);
  document.querySelector('[data-action="physicalCount"]')?.addEventListener('click',()=>toast('Prototipo: aquí se capturaría un conteo físico.'));
  document.querySelector('[data-action="newOrder"]')?.addEventListener('click',newOrderDialog);
  document.querySelector('[data-action="autoPlan"]')?.addEventListener('click',()=>{state.orders.filter(o=>o.stage==='waiting_material'&&o.palletSpec).forEach(o=>{o.materialPlan=buildOrderMaterialPlan(o);o.woodNeed=o.materialPlan.totalRaw});save();toast('Planes de material recalculados con inventario actual.');render()});
  document.getElementById('historyDays')?.addEventListener('change',e=>{state.settings.historyDays=Number(e.target.value);save();toast('Retención actualizada a '+e.target.value+' días.')});
  document.getElementById('ordersSearch')?.addEventListener('input',e=>filterBySearch('[data-order-row]',e.target.value));
  document.getElementById('productionSearch')?.addEventListener('input',e=>filterBySearch('[data-production-row]',e.target.value));
  document.getElementById('loadSearch')?.addEventListener('input',e=>filterBySearch('[data-load-card]',e.target.value));
}
function filterBySearch(selector,value){const q=String(value||'').trim().toLowerCase();document.querySelectorAll(selector).forEach(el=>{el.style.display=!q||String(el.dataset.search||'').includes(q)?'':'none'})}
function receiveWoodDialog(){openDialog('Recibir madera','Entrada de materia prima',`<div class="form-grid"><label><span>Medida</span><select id="rwSize">${state.lumber.map(x=>`<option value="${x.id}">${x.size} · calidad #${x.grade}</option>`).join('')}</select></label><label><span>Cantidad de piezas</span><input id="rwQty" type="number" min="1" value="100"></label></div><div class="dialog-actions"><button type="button" class="btn secondary" id="rwCancel">Cancelar</button><button type="button" class="btn" id="rwSave">Recibir</button></div>`);document.getElementById('rwCancel').onclick=closeDialog;document.getElementById('rwSave').onclick=()=>{const l=lumberById(document.getElementById('rwSize').value);l.qty+=Number(document.getElementById('rwQty').value)||0;save();closeDialog();toast('Madera recibida y disponible.');render()}}
function addMaterialDialog(){openDialog('Agregar tipo de madera','Catálogo configurable',`<div class="form-grid"><label><span>Categoría</span><select id="amCategory"><option value="raw">Materia prima</option><option value="finished">Pieza ya cortada</option></select></label><label><span>Familia</span><input id="amFamily" placeholder="2x4, 2x6, 4x4, 4x6, 3x4..."></label><label><span>Largo</span><input id="amLength" type="number" min="1" value="8"></label><label><span>Unidad del largo</span><select id="amUnit"><option value="ft">pies (materia prima)</option><option value="in">pulgadas (pieza lista)</option></select></label><label><span>Calidad</span><select id="amGrade">${[1,2,3,4].map(g=>`<option value="${g}">#${g}</option>`).join('')}</select></label><label><span>Cantidad inicial</span><input id="amQty" type="number" min="0" value="0"></label><label><span>Mínimo</span><input id="amMin" type="number" min="0" value="0"></label></div><div class="dialog-actions"><button class="btn secondary" id="amCancel">Cancelar</button><button class="btn" id="amSave">Agregar al catálogo</button></div>`);document.getElementById('amCancel').onclick=closeDialog;document.getElementById('amSave').onclick=()=>{const category=document.getElementById('amCategory').value,family=document.getElementById('amFamily').value.trim().toLowerCase();if(!family){toast('Indica la familia de madera.');return}const len=Math.max(1,Number(document.getElementById('amLength').value)||1),grade=Number(document.getElementById('amGrade').value)||2,qty=Math.max(0,Number(document.getElementById('amQty').value)||0),min=Math.max(0,Number(document.getElementById('amMin').value)||0),id='MAT-'+Date.now();const item={id,category,family,grade,qty,reserved:0,min,size:`${family.replace('x','×')} × ${len} ${category==='raw'?'ft':'in'}${category==='finished'?' · pieza lista':''}`};if(category==='raw')item.lengthFt=len;else item.pieceLengthIn=len;state.lumber.push(item);save();closeDialog();toast('Tipo de madera agregado.');render()}}
function convertWoodFromView(){const id=document.getElementById('convSource')?.value,qty=Math.max(1,Number(document.getElementById('convQty')?.value)||1),src=lumberById(id);if(!src)return;if(availableOf(src)<qty){toast('No hay suficiente madera fuente disponible.');return}const target=src.family==='4x4'?'2x4':src.family==='4x6'?'2x6':null;if(!target){toast('Esta fuente no tiene conversión configurada.');return}src.qty-=qty;let dst=state.lumber.find(x=>x.category==='raw'&&x.family===target&&Number(x.lengthFt)===Number(src.lengthFt)&&Number(x.grade)===Number(src.grade));if(!dst){dst={id:'CV-'+Date.now(),category:'raw',family:target,size:`${target.replace('x','×')} × ${src.lengthFt} ft`,lengthFt:src.lengthFt,grade:src.grade,qty:0,reserved:0,min:0};state.lumber.push(dst)}dst.qty+=qty*2;addNote(`Conversión manual: ${qty} ${src.size} → ${qty*2} ${dst.size}.`);save();toast('Conversión registrada en inventario.');render()}
function estimateOrderMaterial(spec){return buildMaterialPlan(spec)}
function boardRowsHtml(side,rows){return `<div class="board-editor" data-board-side="${side}"><div class="board-editor-head"><b>${side==='top'?'Tablas arriba':'Tablas abajo'}</b><button type="button" class="btn ghost" data-add-board="${side}">+ Agregar tipo de tabla</button></div>${rows.map((r,i)=>`<div class="board-row board-row-v09" data-board-row="${side}-${i}"><label><span>Tabla</span><select data-board-width><option value="4" ${Number(r.width)===4?'selected':''}>1×4</option><option value="6" ${Number(r.width)===6?'selected':''}>1×6</option></select></label><label><span>Largo de tabla (in)</span><input data-board-length type="number" min="1" value="${Number(r.length)||40}"></label><label><span>Cantidad por pallet</span><input data-board-qty type="number" min="0" value="${Number(r.qty)||0}"></label><label><span>Calidad requerida (1 mejor)</span><select data-board-grade>${[1,2,3,4].map(g=>`<option value="${g}" ${Number(r.grade)===g?'selected':''}>#${g}</option>`).join('')}</select></label><button type="button" class="remove-board" data-remove-board="${side}-${i}" aria-label="Eliminar tipo">×</button></div>`).join('')}<div class="deck-help small">El largo de las tablas de arriba y de abajo es independiente del ancho general del pallet.</div></div>`}
function makeDeckSequence(rows,existing=[]){const target=[];for(const r of rows||[])for(let i=0;i<Math.max(0,Number(r.qty)||0);i++)target.push({width:Number(r.width)||4,length:Number(r.length)||40,grade:Number(r.grade)||2});if(Array.isArray(existing)&&existing.length===target.length){const counts=a=>a.reduce((m,x)=>{const k=`${x.width}|${x.length}|${x.grade}`;m[k]=(m[k]||0)+1;return m},{}),a=counts(target),b=counts(existing);if(JSON.stringify(Object.keys(a).sort().map(k=>[k,a[k]]))===JSON.stringify(Object.keys(b).sort().map(k=>[k,b[k]])))return existing.map(x=>({...x}))}return target}
function deckSequenceHtml(side,seq){return `<div class="deck-sequence" data-deck-sequence="${side}"><div class="deck-sequence-head"><b>${side==='top'?'Orden de tablas arriba':'Orden de tablas abajo'}</b><span class="small">Arrastra o usa ← → para cambiar posiciones</span></div><div class="deck-strip">${seq.map((b,i)=>`<div class="deck-board board-${b.width}" draggable="true" data-deck-side="${side}" data-deck-index="${i}" title="1×${b.width} × ${b.length} in"><span>${i+1}</span><b>1×${b.width}</b><small>${b.length}\"</small><div class="deck-move"><button type="button" data-deck-left="${side}-${i}" aria-label="Mover izquierda">←</button><button type="button" data-deck-right="${side}-${i}" aria-label="Mover derecha">→</button></div></div>`).join('')}</div></div>`}
function palletDrawingSvg(spec,side='top'){const seq=makeDeckSequence(side==='top'?spec.topBoards:spec.bottomBoards,spec[side+'Sequence']||[]),W=500,H=250,pad=22,availW=W-pad*2,availH=H-pad*2,maxLen=Math.max(Number(spec.length)||1,...seq.map(b=>Number(b.length)||1)),count=Math.max(1,seq.length),gap=5,band=(availH-gap*(count-1))/count;const boards=seq.map((b,i)=>{const len=Math.min(availW,availW*(Number(b.length)||maxLen)/maxLen),y=pad+i*(band+gap),x=pad+(availW-len)/2;return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${len.toFixed(1)}" height="${Math.max(8,band).toFixed(1)}" rx="3" class="svg-board svg-board-${b.width}"/><text x="${(x+5).toFixed(1)}" y="${(y+Math.min(band-3,14)).toFixed(1)}" class="svg-label">1×${b.width} · ${b.length}\"</text>`}).join('');return `<svg viewBox="0 0 ${W} ${H}" class="pallet-svg" role="img" aria-label="Vista ${side==='top'?'superior':'inferior'} del pallet"><rect x="${pad}" y="${pad}" width="${availW}" height="${availH}" rx="8" class="svg-frame"/>${boards}</svg>`}
function productSpecNote(p){const top=makeDeckSequence(p.topBoards,p.topSequence),bottom=makeDeckSequence(p.bottomBoards,p.bottomSequence),fmt=a=>a.length?a.map(x=>`1×${x.width}×${x.length}\"`).join(' – '):'Sin tablas';const r=palletTypeRules(p.type);let base='';if(r.base==='runner')base=`${p.runners||0} runners 2×4`;else if(r.base==='block')base=(p.blocks||[]).map(b=>`${b.qty||0} blocks ${b.family}×${b.length}\"`).join(', ');else base=`${p.basePieces||0} piezas base de crate`;return `<div class="spec-note"><b>Nota de especificación</b><div>${p.length}×${p.width} · ${r.label} · ${p.qty} pallets</div><div><b>Arriba:</b> ${fmt(top)}</div><div><b>Abajo:</b> ${fmt(bottom)}</div><div><b>Base:</b> ${base}</div></div>`}
function productDraft(){return {templateId:'',templateName:'',length:48,width:40,qty:10,type:'4-way-runner',runners:3,runnerGrade:2,blocks:[{family:'4x4',length:4,qty:9,grade:1}],basePieces:3,topBoards:[{width:4,qty:5,grade:2,length:40}],bottomBoards:[{width:4,qty:3,grade:2,length:40},{width:6,qty:2,grade:2,length:40}],topSequence:[],bottomSequence:[],allowConversions:{from4x4:false,from4x6:false},saveTemplate:false}}
function newOrderDialog(){
  const draft={internalId:String(Math.max(1,Number(state.settings.nextOrderNumber)||1)).padStart(4,'0'),customer:'',clientOrder:'',due:'',shipping:'pickup',condition:'new',notes:'',products:[],current:productDraft()};
  const phase1=()=>{openDialog('Nueva orden · Paso 1 de 2','Datos administrativos de la orden',`<div class="wizard-steps"><span class="wizard-step active">1 Orden</span><span class="wizard-step">2 Productos / pallets</span></div><div class="notification info"><b>Orden interna #${draft.internalId}</b> · se asignará automáticamente al guardar.</div><div class="form-grid section"><label><span>Cliente</span><input id="noCustomer" value="${draft.customer}" placeholder="Nombre del cliente"></label><label><span>Número de orden del cliente (opcional)</span><input id="noClientOrder" value="${draft.clientOrder}" placeholder="PO / referencia del cliente"></label><label><span>Fecha / entrega</span><input id="noDue" value="${draft.due}" placeholder="Hoy, mañana o fecha"></label><label><span>Tipo de entrega</span><select id="noShip"><option value="pickup" ${draft.shipping==='pickup'?'selected':''}>Recogida del cliente</option><option value="factory" ${draft.shipping==='factory'?'selected':''}>Envío de fábrica</option></select></label><label><span>Condición</span><select id="noCondition"><option value="new">Pallet nuevo</option><option value="repair">Reparación / reacondicionado</option></select></label><label class="wide"><span>Notas</span><textarea id="noNotes">${draft.notes}</textarea></label></div><div class="dialog-actions"><button class="btn secondary" id="noCancel">Cancelar</button><button class="btn" id="noNext">Continuar →</button></div>`);document.getElementById('noCancel').onclick=closeDialog;document.getElementById('noNext').onclick=()=>{draft.customer=document.getElementById('noCustomer').value.trim();if(!draft.customer){toast('Escribe el cliente.');return}draft.clientOrder=document.getElementById('noClientOrder').value.trim();draft.due=document.getElementById('noDue').value.trim();draft.shipping=document.getElementById('noShip').value;draft.condition=document.getElementById('noCondition').value;draft.notes=document.getElementById('noNotes').value;phase2()}};
  const phase2=()=>{const c=draft.current,rules=palletTypeRules(c.type),opts=(state.palletTemplates||[]).map(t=>`<option value="${t.id}">${t.name}</option>`).join(''),added=draft.products.map((p,i)=>`<div class="product-chip"><div><b>${p.length}×${p.width}</b> · ${p.qty} · ${palletTypeRules(p.type).label}<div class="small">Pila ${palletTypeRules(p.type).maxHeight} · ${palletTypeRules(p.type).canRotate?'giro automático':'sin giro'}</div></div><button class="remove-board" data-remove-product="${i}">×</button></div>`).join('');const typeBase=rules.base;openDialog('Nueva orden · Paso 2 de 2',`#${draft.internalId} · ${draft.customer}`,`<div class="wizard-steps"><span class="wizard-step done">1 Orden</span><span class="wizard-step active">2 Productos / pallets</span></div>${added?`<div class="product-list"><b>Medidas agregadas a esta orden</b>${added}</div>`:''}<div class="template-bar section"><label><span>Plantilla</span><select id="noTemplate"><option value="">— Describir manualmente —</option>${opts}</select></label><button class="btn ghost" id="noApplyTemplate">Aplicar</button></div><div class="form-grid section"><label><span>Largo pallet (in)</span><input id="noLength" type="number" min="1" value="${c.length}"></label><label><span>Ancho pallet (in)</span><input id="noWidth" type="number" min="1" value="${c.width}"></label><label><span>Cantidad</span><input id="noQty" type="number" min="1" value="${c.qty}"></label><label><span>Tipo de producto</span><select id="noType">${['2-way-runner','4-way-runner','2-way-block','4-way-block','2-way-crate','4-way-crate'].map(t=>`<option value="${t}" ${c.type===t?'selected':''}>${palletTypeRules(t).label}</option>`).join('')}</select></label></div><div class="notification info"><b>Reglas automáticas:</b> ${rules.label} → máximo por pila ${rules.maxHeight}; ${rules.canRotate?'se puede girar':'no se gira'}. Estos valores no se capturan aquí; se pueden ajustar después en LoadMaster.</div>${typeBase==='runner'?`<div class="form-grid section"><label><span>Runners 2×4 por pallet</span><input id="noRunners" type="number" min="0" value="${c.runners}"></label><label><span>Calidad runners</span><select id="noRunnerGrade">${[1,2,3,4].map(g=>`<option value="${g}" ${c.runnerGrade===g?'selected':''}>#${g}</option>`).join('')}</select></label></div>`:typeBase==='block'?`<div class="board-editor"><div class="board-editor-head"><b>Blocks por pallet</b></div><div class="board-row"><label><span>Madera block</span><select id="noBlockFamily"><option value="4x4" ${c.blocks[0]?.family==='4x4'?'selected':''}>4×4</option><option value="4x6" ${c.blocks[0]?.family==='4x6'?'selected':''}>4×6</option></select></label><label><span>Largo block (in)</span><select id="noBlockLength"><option value="4" ${Number(c.blocks[0]?.length)===4?'selected':''}>4</option><option value="6" ${Number(c.blocks[0]?.length)===6?'selected':''}>6</option></select></label><label><span>Cantidad por pallet</span><input id="noBlockQty" type="number" min="1" value="${c.blocks[0]?.qty||9}"></label><label><span>Calidad</span><select id="noBlockGrade">${[1,2,3,4].map(g=>`<option value="${g}" ${Number(c.blocks[0]?.grade||1)===g?'selected':''}>#${g}</option>`).join('')}</select></label></div></div>`:`<div class="form-grid section"><label><span>Piezas base 2×4 por crate</span><input id="noBasePieces" type="number" min="0" value="${c.basePieces||3}"></label><label><span>Calidad base</span><select id="noRunnerGrade">${[1,2,3,4].map(g=>`<option value="${g}" ${c.runnerGrade===g?'selected':''}>#${g}</option>`).join('')}</select></label></div>`}${boardRowsHtml('top',c.topBoards)}${boardRowsHtml('bottom',c.bottomBoards)}<details class="advanced-box pallet-design-box"><summary>Diseño visual y posición de tablas</summary><div id="visualDeckEditor"></div></details><details class="advanced-box"><summary>Opciones avanzadas de material alternativo</summary><p class="small">Por defecto el sistema usa solo 2×4/2×6 y blocks 4×4/4×6 definidos. Si falta material, estas casillas solo permiten mostrar sugerencias; nunca convierten inventario automáticamente.</p><label class="check-row"><input id="allow4x4" type="checkbox" ${c.allowConversions.from4x4?'checked':''}><span>Permitir sugerir 4×4 → 2×4</span></label><label class="check-row"><input id="allow4x6" type="checkbox" ${c.allowConversions.from4x6?'checked':''}><span>Permitir sugerir 4×6 → 2×6</span></label></details><div class="estimate-box" id="materialEstimate">${materialPlanHtml(buildMaterialPlan(c))}</div><div class="template-save"><label class="check-row"><input id="noSaveTemplate" type="checkbox"><span>Guardar esta descripción como plantilla</span></label><input id="noTemplateName" value="${c.templateName||''}" placeholder="Ej. 48×40 – Geek Industrial"></div><div class="dialog-actions"><button class="btn secondary" id="noBack">← Datos de orden</button><button class="btn secondary" id="noAddProduct">+ Agregar esta medida</button><button class="btn" id="noSave">Crear orden con ${draft.products.length+1} medida${draft.products.length?'s':''}</button></div>`);
    const readCurrent=()=>{c.length=Math.max(1,Number(document.getElementById('noLength').value)||1);c.width=Math.max(1,Number(document.getElementById('noWidth').value)||1);c.qty=Math.max(1,Number(document.getElementById('noQty').value)||1);const selectedType=document.getElementById('noType').value,oldRules=palletTypeRules(c.type);if(oldRules.base==='runner')c.runners=Math.max(0,Number(document.getElementById('noRunners')?.value)||0);if(oldRules.base==='crate')c.basePieces=Math.max(0,Number(document.getElementById('noBasePieces')?.value)||0);c.runnerGrade=Number(document.getElementById('noRunnerGrade')?.value)||2;if(oldRules.base==='block'&&document.getElementById('noBlockFamily'))c.blocks=[{family:document.getElementById('noBlockFamily').value,length:Number(document.getElementById('noBlockLength').value)||4,qty:Number(document.getElementById('noBlockQty').value)||9,grade:Number(document.getElementById('noBlockGrade').value)||1}];c.type=selectedType;c.allowConversions={from4x4:Boolean(document.getElementById('allow4x4')?.checked),from4x6:Boolean(document.getElementById('allow4x6')?.checked)};c.saveTemplate=Boolean(document.getElementById('noSaveTemplate')?.checked);c.templateName=document.getElementById('noTemplateName')?.value.trim()||'';for(const side of ['top','bottom'])c[side==='top'?'topBoards':'bottomBoards']=[...document.querySelectorAll(`[data-board-side="${side}"] [data-board-row]`)].map(row=>({width:Number(row.querySelector('[data-board-width]').value)||4,length:Math.max(1,Number(row.querySelector('[data-board-length]').value)||c.width||40),qty:Math.max(0,Number(row.querySelector('[data-board-qty]').value)||0),grade:Number(row.querySelector('[data-board-grade]').value)||2}))};
    const renderVisualDeck=()=>{const host=document.getElementById('visualDeckEditor');if(!host)return;c.topSequence=makeDeckSequence(c.topBoards,c.topSequence);c.bottomSequence=makeDeckSequence(c.bottomBoards,c.bottomSequence);host.innerHTML=`<div class="pallet-preview-grid"><div><h4>Vista superior</h4>${palletDrawingSvg(c,'top')}${deckSequenceHtml('top',c.topSequence)}</div><div><h4>Vista inferior</h4>${palletDrawingSvg(c,'bottom')}${deckSequenceHtml('bottom',c.bottomSequence)}</div></div>${productSpecNote(c)}`;const move=(side,i,d)=>{const key=side==='top'?'topSequence':'bottomSequence',a=c[key],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderVisualDeck()};host.querySelectorAll('[data-deck-left]').forEach(b=>b.onclick=()=>{const [side,i]=b.dataset.deckLeft.split('-');move(side,Number(i),-1)});host.querySelectorAll('[data-deck-right]').forEach(b=>b.onclick=()=>{const [side,i]=b.dataset.deckRight.split('-');move(side,Number(i),1)});let drag=null;host.querySelectorAll('[data-deck-index]').forEach(elm=>{elm.addEventListener('dragstart',()=>{drag={side:elm.dataset.deckSide,index:Number(elm.dataset.deckIndex)}});elm.addEventListener('dragover',e=>e.preventDefault());elm.addEventListener('drop',e=>{e.preventDefault();if(!drag||drag.side!==elm.dataset.deckSide)return;const key=drag.side==='top'?'topSequence':'bottomSequence',a=c[key],to=Number(elm.dataset.deckIndex),[item]=a.splice(drag.index,1);a.splice(to,0,item);drag=null;renderVisualDeck()})})};
    const refresh=()=>{readCurrent();document.getElementById('materialEstimate').innerHTML=materialPlanHtml(buildMaterialPlan(c));renderVisualDeck()};document.querySelectorAll('#noLength,#noWidth,#noQty,#noRunners,#noBasePieces,#noRunnerGrade,[data-board-row] input,[data-board-row] select,#allow4x4,#allow4x6,#noBlockFamily,#noBlockLength,#noBlockQty,#noBlockGrade').forEach(x=>x?.addEventListener('input',refresh));renderVisualDeck();document.getElementById('noType').onchange=()=>{readCurrent();phase2()};document.querySelectorAll('[data-add-board]').forEach(b=>b.onclick=()=>{readCurrent();const arr=b.dataset.addBoard==='top'?c.topBoards:c.bottomBoards;arr.push({width:4,length:c.width||40,qty:1,grade:2});phase2()});document.querySelectorAll('[data-remove-board]').forEach(b=>b.onclick=()=>{readCurrent();const [side,i]=b.dataset.removeBoard.split('-');const arr=side==='top'?c.topBoards:c.bottomBoards;arr.splice(Number(i),1);phase2()});document.querySelectorAll('[data-remove-product]').forEach(b=>b.onclick=()=>{draft.products.splice(Number(b.dataset.removeProduct),1);phase2()});document.getElementById('noApplyTemplate').onclick=()=>{const t=templateById(document.getElementById('noTemplate').value);if(!t)return;draft.current={...productDraft(),...clone(t),qty:c.qty,templateId:t.id,templateName:t.name,allowConversions:t.allowConversions||{from4x4:false,from4x6:false}};phase2()};document.getElementById('noBack').onclick=()=>{readCurrent();phase1()};
    const snapshot=()=>{readCurrent();const r=palletTypeRules(c.type);return {...clone(c),name:`${c.length}×${c.width}`,maxHeight:r.maxHeight,canRotate:r.canRotate}};
    document.getElementById('noAddProduct').onclick=()=>{const p=snapshot();draft.products.push(p);if(p.saveTemplate&&p.templateName){state.palletTemplates.push({...clone(p),id:'TPL-'+Date.now(),name:p.templateName,customer:draft.customer});save()}draft.current=productDraft();toast('Medida agregada a la orden.');phase2()};
    document.getElementById('noSave').onclick=()=>{const last=snapshot(),products=[...draft.products,last];if(last.saveTemplate&&last.templateName){state.palletTemplates.push({...clone(last),id:'TPL-'+Date.now(),name:last.templateName,customer:draft.customer})}const id=nextOrderId(),qty=products.reduce((n,p)=>n+p.qty,0),product=products.length===1?`${products[0].length}×${products[0].width}`:`${products.length} medidas · carga mixta`,loadItems=products.map(p=>{const r=palletTypeRules(p.type);return {name:`${p.length}×${p.width}`,length:p.length,width:p.width,quantity:p.qty,maxHeight:r.maxHeight,canRotate:r.canRotate,type:p.type}}),order={id,clientOrder:draft.clientOrder,customer:draft.customer,product,qty,due:draft.due||'Sin fecha',shipping:draft.shipping,condition:draft.condition,stage:'waiting_material',notes:draft.notes,products:clone(products),palletSpecs:clone(products),palletSpec:clone(products[0]),palletSku:products.length===1?(products[0].templateName||`${products[0].length}×${products[0].width}`):`MIX-${id}`,trailerWidth:96,trailerLength:628,loadItems};order.materialPlan=buildOrderMaterialPlan(order);order.woodNeed=order.materialPlan.totalRaw;state.orders.push(order);save();closeDialog();toast(`Orden #${id} creada con ${products.length} medida(s).`);navigate('ordenes')};
  };phase1()
}
function materialPlanHtml(p){const suggestions=p.conversionSuggestions||[];if(p.shortages?.length)return `<b>Plan automático de material</b><div class="plan-status bad">No alcanza el inventario actual</div><div class="small">${p.shortages.map(x=>`${x.label}: faltan ${x.missing} piezas/cortes de ${x.cutLength} in · ${x.family} · calidad #${x.grade} o mejor`).join('<br>')}</div>${suggestions.length?`<div class="conversion-suggest"><b>Opciones sugeridas (requieren tu autorización)</b>${suggestions.slice(0,4).map(x=>`<div>${x.source} → ${x.target}: aprox. ${x.rawNeeded} piezas fuente para ${x.label}</div>`).join('')}<div class="small">Ve a Conversión de madera para ejecutarla manualmente.</div></div>`:''}`;const lines=Object.entries(p.stockTotals||{}).map(([id,n])=>{const w=lumberById(id);return `<li><b>${n}</b> ${w?.category==='finished'?'piezas listas':'piezas madre'} de ${w?.size||id} · calidad #${w?.grade||'?'}</li>`}).join('');return `<b>Plan automático de material</b><div class="plan-status ok">Inventario suficiente</div><ul class="material-plan-list">${lines||'<li>No requiere material.</li>'}</ul><div class="small">Prioridad: pieza lista exacta → materia prima correcta → sin conversión automática. Desperdicio lineal de corte aprox. ${Math.round(p.wasteIn||0)} in.</div>`}
function openOrderSpecification(id){const o=orderById(id);if(!o)return;const products=orderProducts(o);const body=products.map((p,i)=>`<section class="spec-product"><div class="section-head"><div><h3>${p.templateName||p.name||`${p.length}×${p.width}`}</h3><p>${p.qty} pallets · ${palletTypeRules(p.type).label}</p></div></div><div class="pallet-preview-grid"><div><h4>Vista superior</h4>${palletDrawingSvg(p,'top')}</div><div><h4>Vista inferior</h4>${palletDrawingSvg(p,'bottom')}</div></div>${productSpecNote(p)}</section>`).join('')||'<div class="empty-state">Esta orden no tiene especificación técnica guardada.</div>';openDialog(`Especificación · Orden #${o.id}`,`${o.customer}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}`,`${body}<div class="dialog-actions"><button class="btn secondary" id="specClose">Cerrar</button><button class="btn" id="specPrint">Imprimir hoja de fabricación</button></div>`);document.getElementById('specClose').onclick=closeDialog;document.getElementById('specPrint').onclick=()=>window.print()}
function startCut(id){const o=orderById(id);const plan=buildOrderMaterialPlan(o);o.materialPlan=plan;if(plan.shortages.length){save();toast(`No alcanza inventario: ${plan.shortages[0].label}, faltan ${plan.shortages[0].missing}.`);render();return}if(!reserveWood(o)){toast('El inventario cambió y ya no alcanza para este plan.');render();return}o.stage='cutting';addNote(`Orden #${o.id}: plan automático reservado y corte iniciado.`);save();toast('Corte iniciado; madera óptima reservada.');render()}
function finishCut(id){const o=orderById(id);consumeReservedWood(o);o.stage='material_ready';addNote(`Orden #${o.id}: material listo. Fabricación ya puede recogerlo.`);save();toast('Material listo → apareció en Fabricación.');render()}
function startBuild(id){const o=orderById(id);o.stage='building';addNote(`Orden #${o.id}: fabricación iniciada.`);save();toast('Fabricación iniciada.');render()}
function finishBuild(id){const o=orderById(id);o.stage='ready_load';const products=orderProducts(o);if(products.length){for(const p of products){const sku=p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty+=(Number(p.qty)||0);f.reserved+=(Number(p.qty)||0)}}else{const f=findFinished(o.palletSku);f.qty+=o.qty;f.reserved+=o.qty}addNote(`Orden #${o.id}: ${o.qty} pallets terminados → lista para carga.`);save();toast('Fabricación terminada → orden enviada a Carga.');render()}
function openLoadOrder(id){const o=orderById(id);const pickup=o.shipping==='pickup';openDialog(`Pedido #${o.id}`,`${o.customer}${o.clientOrder?` · Cliente ${o.clientOrder}`:''} · ${pickup?'Recogida del cliente':'Envío de fábrica'}`,`<div class="workflow"><span class="step active">1 Verificar</span><span class="step">2 Optimizar / cargar</span><span class="step">3 Evidencia</span><span class="step">4 Firma</span><span class="step">5 Cerrar</span></div><div class="detail-grid"><div class="detail"><b>Producto</b>${o.product}</div><div class="detail"><b>Cantidad</b>${o.qty} pallets</div><div class="detail"><b>Transporte</b>${pickup?'Cliente trae tráiler':'Fábrica pone chofer y tráiler'}</div><div class="detail"><b>Estado</b>${stageLabel(o.stage)}</div></div><div class="stage-actions"><button type="button" class="btn secondary" id="orderLM">Preparar / optimizar carga</button><button type="button" class="btn" id="markLoading">Marcar cargando</button></div><div class="section evidence"><b>Foto / factura firmada</b><p class="small">La foto es opcional, pero se conserva porque normalmente sirve como evidencia de la factura firmada.</p><input id="evidenceFile" type="file" accept="image/*"><div class="evidence-preview" id="evidencePreview">Sin foto seleccionada.</div></div><div class="section form-grid"><label class="wide"><span>Firma / nombre de quien recibe</span><input id="signatureName" placeholder="Nombre o firma registrada"></label><label class="wide"><span>Notas de carga</span><textarea id="loadNotes">${o.notes||''}</textarea></label></div><div class="dialog-actions"><button type="button" class="btn secondary" id="loadCancel">Cerrar</button><button type="button" class="btn" id="finishDispatch">${pickup?'Completar recogida':'Despachar / en tránsito'}</button></div>`);
  document.getElementById('loadCancel').onclick=closeDialog;document.getElementById('orderLM').onclick=()=>openLoadPreparation(o.id);document.getElementById('markLoading').onclick=()=>{o.stage='loading';save();toast('Pedido marcado como cargando.');};document.getElementById('evidenceFile').onchange=e=>{document.getElementById('evidencePreview').textContent=e.target.files[0]?`Foto seleccionada: ${e.target.files[0].name}`:'Sin foto seleccionada.'};document.getElementById('finishDispatch').onclick=()=>{const sig=document.getElementById('signatureName').value.trim();const hasPhoto=Boolean(document.getElementById('evidenceFile').files[0]);o.notes=document.getElementById('loadNotes').value;if(pickup){completeOrder(o,`${sig?'Firma':'Sin firma'}${hasPhoto?' + foto factura':''}`)}else{o.stage='transit';o.evidence=`${sig?'Firma salida':'Sin firma salida'}${hasPhoto?' + foto':''}`;addNote(`Orden #${o.id}: salió de fábrica y está en tránsito.`);save();closeDialog();toast('Pedido en tránsito.');render()}}
}
function completeDelivery(id){const o=orderById(id);completeOrder(o,(o.evidence||'Salida registrada')+' + entrega confirmada')}
function completeOrder(o,evidence){const products=orderProducts(o);if(products.length){for(const p of products){const sku=p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty=Math.max(0,f.qty-(Number(p.qty)||0));f.reserved=Math.max(0,f.reserved-(Number(p.qty)||0))}}else{const f=findFinished(o.palletSku);f.qty=Math.max(0,f.qty-o.qty);f.reserved=Math.max(0,f.reserved-o.qty)}state.history.unshift({id:o.id,clientOrder:o.clientOrder||'',customer:o.customer,shipping:o.shipping,completed:'Hoy',evidence:evidence||'Registro completado'});state.orders=state.orders.filter(x=>x.id!==o.id);addNote(`Orden #${o.id}: completada y enviada al historial.`);save();closeDialog();toast('Orden completada → Historial.');render()}
function openLoadPreparation(id){
  const o=orderById(id);if(!o)return;const items=loadItemsFor(o);if(!items.length){toast('Esta orden no tiene medidas válidas para LoadMaster.');return}
  const rows=items.map((x,i)=>`<tr data-prep-row="${i}"><td><b>${x.name||`${x.length}×${x.width}`}</b><div class="small">${palletTypeRules(x.type).label}</div></td><td><input class="qty-locked" type="number" value="${Number(x.quantity)||1}" readonly></td><td><input data-prep-height type="number" min="1" value="${Math.max(1,Number(x.maxHeight)||palletTypeRules(x.type).maxHeight)}"></td><td><b>${palletTypeRules(x.type).canRotate?'Sí':'No'}</b><div class="small">Automático por tipo</div></td></tr>`).join('');
  openDialog(`Preparar carga #${o.id}`,`${o.customer} · ${loadTotal(items)} pallets`,`<div class="notification info"><b>Datos conectados.</b> Cantidad, tipo y giro vienen de la orden. Aquí solo ajustas la altura máxima si esta carga necesita una excepción.</div><div class="prep-trailer"><label><span>Ancho tráiler (in)</span><input id="prepTrailerWidth" type="number" value="${Number(o.trailerWidth)||96}"></label><label><span>Largo tráiler (in)</span><input id="prepTrailerLength" type="number" value="${Number(o.trailerLength)||628}"></label></div><div class="table-wrap prep-table"><table><thead><tr><th>Medida / tipo</th><th>Cantidad</th><th>Máximo por pila</th><th>Giro</th></tr></thead><tbody>${rows}</tbody></table></div><div class="dialog-actions"><button class="btn secondary" id="prepCancel">Volver</button><button class="btn" id="prepLaunch">Abrir LoadMaster a pantalla completa</button></div>`);
  document.getElementById('prepCancel').onclick=()=>{closeDialog();openLoadOrder(id)};document.getElementById('prepLaunch').onclick=()=>{const prepared=items.map((item,i)=>{const row=document.querySelector(`[data-prep-row="${i}"]`),rules=palletTypeRules(item.type);return {...item,quantity:Number(item.quantity)||1,maxHeight:Math.max(1,Number(row.querySelector('[data-prep-height]').value)||rules.maxHeight),canRotate:rules.canRotate,type:item.type}});o.loadItems=clone(prepared);o.trailerWidth=Math.max(1,Number(document.getElementById('prepTrailerWidth').value)||96);o.trailerLength=Math.max(1,Number(document.getElementById('prepTrailerLength').value)||628);save();localStorage.setItem(LM_HANDOFF,JSON.stringify({version:2,source:'Pallet Operations',orderId:o.id,customer:o.customer,shipping:o.shipping,trailer:{width:o.trailerWidth,length:o.trailerLength},items:prepared,returnUrl:'index.html#carga',createdAt:new Date().toISOString()}));window.location.href=`loadmaster.html?platform=1&order=${encodeURIComponent(o.id)}`}
}
function openLoadMaster(){
  const payload={version:1,source:'Pallet Operations',orderId:'manual',customer:'Carga manual',trailer:{width:96,length:628},items:[],returnUrl:'index.html#carga',createdAt:new Date().toISOString()};
  localStorage.setItem(LM_HANDOFF,JSON.stringify(payload));window.location.href='loadmaster.html?platform=1';
}

document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('resetDemo').addEventListener('click',()=>{if(confirm('¿Restablecer todos los datos del prototipo?')){state=normalizeState(structuredClone(initialState));save();toast('Demo restablecida.');render()}});
if(!views[currentView])currentView='inicio';
render();
